{
  "name": "accord-core",
  "version": "0.1.1",
  "description": "Multi-model consensus MCP server — query AI models in parallel for agreement, debate, review, and brainstorm. Works with any MCP client.",
  "type": "module",
  "main": "src/server.js",
  "bin": {
    "accord-core": "src/server.js",
    "accord-tui": "src/accord-tui.js"
  },
  "scripts": {
    "start": "node src/server.js",
    "test": "node test/test.js"
  },
  "keywords": [
    "mcp",
    "council",
    "multi-model",
    "openrouter",
    "ai",
    "llm",
    "mimocode",
    "opencode",
    "debate",
    "brainstorm",
    "consensus",
    "review"
  ],
  "author": "kira",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/ces-cimes/accord-core.git"
  },
  "homepage": "https://github.com/ces-cimes/accord-core#readme",
  "bugs": {
    "url": "https://github.com/ces-cimes/accord-core/issues"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.29.0",
    "zod": "^4.4.3"
  },
  "optionalDependencies": {
    "@opentui/core": "^0.5.8"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "files": [
    "src/",
    "LICENSE",
    "README.md"
  ]
}
